//! The native Rust core reproduces the golden parity trajectories bit for bit.
//!
//! The goldens in `parity/golden/` are generated by
//! `parity/generate_golden.py` and also checked against the Python extension
//! and the WebAssembly build. This test catches physics or `libm` changes
//! without needing either binding.

use std::fs;
use std::path::PathBuf;

use icarus_core::{
    Controls, Injection, PHYSICS_VERSION, RecordingSim, Replay, Sim, TELEMETRY_FIELDS,
    VehicleConfig,
};
use serde_json::Value;

const FNV_OFFSET: u64 = 0xCBF2_9CE4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01B3;

fn fnv1a(mut h: u64, values: &[f64]) -> u64 {
    for v in values {
        for byte in v.to_bits().to_le_bytes() {
            h ^= u64::from(byte);
            h = h.wrapping_mul(FNV_PRIME);
        }
    }
    h
}

fn from_hex(v: &Value) -> f64 {
    let text = v.as_str().expect("hex string");
    f64::from_bits(u64::from_str_radix(text, 16).expect("valid hex"))
}

fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../parity/golden")
}

/// The golden files, which must be exactly the cases listed in the manifest.
fn golden_files() -> Vec<PathBuf> {
    let dir = golden_dir();
    let manifest: Value =
        serde_json::from_str(&fs::read_to_string(dir.join("manifest.json")).unwrap()).unwrap();
    let mut expected: Vec<String> = manifest["cases"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect();
    expected.sort();
    let mut on_disk: Vec<String> = fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", dir.display()))
        .filter_map(|entry| entry.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|ext| ext == "json"))
        .filter_map(|p| p.file_stem().map(|s| s.to_string_lossy().into_owned()))
        .filter(|stem| stem != "manifest")
        .collect();
    on_disk.sort();
    assert!(!expected.is_empty(), "empty manifest");
    assert_eq!(on_disk, expected, "golden files do not match the manifest");
    expected
        .iter()
        .map(|name| dir.join(format!("{name}.json")))
        .collect()
}

fn injection(e: &Value) -> Injection {
    let (a, b) = (from_hex(&e["a"]), from_hex(&e["b"]));
    match e["kind"].as_str().unwrap() {
        "gimbal_stuck" => Injection::GimbalStuck { angle: a },
        "thrust_loss" => Injection::ThrustLoss { factor: a },
        "gust" => Injection::Gust {
            amplitude: a,
            duration: b,
        },
        other => panic!("unknown event kind {other}"),
    }
}

fn as_u8(v: &Value) -> u8 {
    u8::try_from(v.as_u64().expect("integer")).expect("fits in u8")
}

#[test]
fn native_core_matches_goldens() {
    for path in golden_files() {
        let golden: Value = serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        let name = golden["name"].as_str().unwrap();
        assert_eq!(Some(name), path.file_stem().and_then(|s| s.to_str()));
        assert_eq!(golden["format"].as_u64(), Some(1), "{name}: golden format");
        assert_eq!(
            golden["physics_version"].as_u64(),
            Some(u64::from(PHYSICS_VERSION)),
            "{name}"
        );
        let fields: Vec<&str> = golden["telemetry_fields"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(fields, TELEMETRY_FIELDS, "{name}: telemetry layout");

        let config = VehicleConfig::from_name(golden["config"].as_str().unwrap()).unwrap();
        let seed: u64 = golden["seed"].as_str().unwrap().parse().unwrap();
        let mut sim = Sim::from_config(config, seed);
        let events = golden["events"].as_array().unwrap();
        let samples = golden["samples"].as_array().unwrap();
        let check = |tick: u64, telemetry: &[f64]| {
            if let Some(s) = samples.iter().find(|s| s["tick"].as_u64() == Some(tick)) {
                let values = s["telemetry"].as_array().unwrap();
                assert_eq!(
                    values.len(),
                    telemetry.len(),
                    "{name} tick {tick}: sample length"
                );
                for (i, want) in values.iter().enumerate() {
                    let got = format!("{:016x}", telemetry[i].to_bits());
                    assert_eq!(
                        got,
                        want.as_str().unwrap(),
                        "{name} tick {tick}: {}",
                        fields[i]
                    );
                }
            }
        };

        let mut h = fnv1a(FNV_OFFSET, &sim.telemetry());
        check(0, &sim.telemetry());
        let mut tick: u64 = 0;
        for run in golden["inputs"].as_array().unwrap() {
            let run = run.as_array().unwrap();
            let count = run[0].as_u64().unwrap();
            let q = [as_u8(&run[1]), as_u8(&run[2]), as_u8(&run[3])];
            for _ in 0..count {
                for e in events.iter().filter(|e| e["tick"].as_u64() == Some(tick)) {
                    sim.inject(injection(e));
                }
                sim.step(Controls::from_quantized(q));
                tick += 1;
                let telemetry = sim.telemetry();
                assert!(
                    telemetry.iter().all(|v| v.is_finite()),
                    "{name}: NaN at tick {tick}"
                );
                h = fnv1a(h, &telemetry);
                check(tick, &telemetry);
            }
        }
        assert_eq!(Some(tick), golden["ticks"].as_u64(), "{name}: tick count");
        assert_eq!(
            sim.outcome().map(|o| o.name()),
            golden["outcome"].as_str(),
            "{name}: outcome"
        );
        assert_eq!(
            Some(u64::from(sim.score())),
            golden["score"].as_u64(),
            "{name}: score"
        );
        assert_eq!(
            format!("{h:016x}"),
            golden["hash"].as_str().unwrap(),
            "{name}: hash"
        );

        // The replay string: re-recording encodes the identical string, and
        // decoding it replays to the final sample.
        let encoded = golden["replay"]
            .as_str()
            .expect("every golden carries its replay");
        let last = samples.last().unwrap();
        assert_eq!(
            last["tick"].as_u64(),
            Some(tick),
            "{name}: last sample at the final tick"
        );
        let mut recorder = RecordingSim::new(config, seed);
        let mut t: u64 = 0;
        for run in golden["inputs"].as_array().unwrap() {
            let run = run.as_array().unwrap();
            let q = [as_u8(&run[1]), as_u8(&run[2]), as_u8(&run[3])];
            for _ in 0..run[0].as_u64().unwrap() {
                for e in events.iter().filter(|e| e["tick"].as_u64() == Some(t)) {
                    recorder.inject(injection(e));
                }
                recorder.step_quantized(q);
                t += 1;
            }
        }
        assert_eq!(
            recorder.replay().encode().unwrap(),
            encoded,
            "{name}: replay encoding"
        );
        let replayed = Replay::decode(encoded).unwrap().run();
        let want: Vec<&str> = last["telemetry"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        let got: Vec<String> = replayed
            .telemetry()
            .iter()
            .map(|v| format!("{:016x}", v.to_bits()))
            .collect();
        assert_eq!(got, want, "{name}: replay final state");
    }
}
